const fs = require('fs');
const Excel = require('exceljs');

async function compareExcelFiles(file1, file2) {
    const workbook1 = new Excel.Workbook();
    const workbook2 = new Excel.Workbook();
    await workbook1.xlsx.readFile(file1);
    await workbook2.xlsx.readFile(file2);

    const sheet1 = workbook1.sheetNames[0];
    const sheet2 = workbook2.sheetNames[0];

    const data1 = workbook1.getWorksheet(sheet1);
    const data2 = workbook2.getWorksheet(sheet2);

    const rows1 = data1.getRows();
    const rows2 = data2.getRows();

    // Compare the rows
    const discrepancies = [];
    for (let i = 0; i < Math.min(rows1.length, rows2.length); i++) {
        const row1 = rows1[i];
        const row2 = rows2[i];
        for (let j = 0; j < Math.min(row1.length, row2.length); j++) {
            if row1[j] !== row2[j] && row1[j] !== undefined && row2[j] !== undefined {
                discrepancies.push({ row: i, column: j, value1: row1[j], value2: row2[j});
            }
        }
    }

    console.log('Discrepancies found:', discrepancies);
    return discrepancies;
}

// Usage
compareExcelFiles('file1.xlsx', 'file2.xlsx');
